export function normalizeProjectCatalog(rows){const seen=new Set();return rows.map(r=>{const id=String(r.id||'').trim(),name=String(r.name||'').trim(),number=String(r.number??r.project_number??'').trim();if(!id||!name||seen.has(id))throw Error('Projektkatalog ohne eindeutige ID/Name');seen.add(id);return{id,name,number,label:String(r.label||[number,name].filter(Boolean).join(' ')),address:String(r.address||''),archived:!!(r.archived??r.archived_at)};});}
export function resolveCatalogProject(catalog,{projectId,project}){if(projectId)return catalog.find(p=>p.id===projectId)||null;const matches=catalog.filter(p=>p.label===project);return matches.length===1?matches[0]:null;}
